package com.rdx.fullscreen.clean;
import java.io.*;
import java.security.MessageDigest;
import java.util.*;
/** Host-only independent oracle, file fixtures, unknown retention and seeded differential checks. */
public final class IndependentValidationTests {
 private static int deterministic,propertyChecks,validCases,malformedCases;
 private static final long SEED=0x4d375244583031L;private static final Random random=new Random(SEED);
 private static void check(String name,boolean yes){if(!yes)throw new AssertionError(name);deterministic++;System.out.println("PASS "+name);}
 private static void property(String name,boolean yes){if(!yes)throw new AssertionError(name+" seed="+SEED+" case="+validCases+"/"+malformedCases);propertyChecks++;}
 private static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte v:b){int n=v&255;s.append(Character.forDigit(n>>>4,16));s.append(Character.forDigit(n&15,16));}return s.toString();}
 private static byte[] read(File f)throws IOException{if(f.length()>1048576)throw new IllegalArgumentException("Fixture file bound");FileInputStream in=new FileInputStream(f);try{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(n>1048576-b.size())throw new IllegalArgumentException("Fixture grew");b.write(buffer,0,n);}return b.toByteArray();}finally{in.close();}}
 private static int[] chunks(int size){List<Integer> sizes=new ArrayList<Integer>();while(size>0){int n=1+random.nextInt(Math.min(73,size));sizes.add(n);size-=n;}int[] out=new int[sizes.size()];for(int i=0;i<out.length;i++)out[i]=sizes.get(i);return out;}
 private static List<AaFrame> frames(byte[] wire,int[] chunks){AaFrameParser p=new AaFrameParser(16384,65536,256);List<AaFrame> out=new ArrayList<AaFrame>();int at=0;for(int n:chunks){out.addAll(p.feed(wire,at,n));at+=n;}if(at!=wire.length)throw new AssertionError("Test partition");p.endOfInput();return out;}
 private static List<AaMessageAssembler.Message> assemble(List<AaFrame> frames){AaMessageAssembler a=new AaMessageAssembler(65536,8,524288);List<AaMessageAssembler.Message> out=new ArrayList<AaMessageAssembler.Message>();for(AaFrame f:frames){AaMessageAssembler.Message m=a.accept(f);if(m!=null)out.add(m);}a.endOfInput();return out;}
 private static String productionMessages(List<AaMessageAssembler.Message> messages){StringBuilder out=new StringBuilder();for(AaMessageAssembler.Message m:messages){if(out.length()!=0)out.append('|');out.append(m.channel).append(':').append(m.flags&12).append(':').append(hex(m.bytes()));}return out.toString();}
 private static String referenceMessages(List<ReferenceWireOracle.Message> messages){StringBuilder out=new StringBuilder();for(ReferenceWireOracle.Message m:messages){if(out.length()!=0)out.append('|');out.append(m.channel).append(':').append(m.flags&12).append(':').append(hex(m.body));}return out.toString();}
 private static String productionFrames(List<AaFrame> frames){StringBuilder out=new StringBuilder();for(AaFrame f:frames){if(out.length()!=0)out.append('|');out.append(f.channel).append(':').append(f.flags).append(':').append(f.totalPlaintextLength).append(':').append(hex(f.body()));}return out.toString();}
 private static String referenceFrames(List<ReferenceWireOracle.Frame> frames){StringBuilder out=new StringBuilder();for(ReferenceWireOracle.Frame f:frames){if(out.length()!=0)out.append('|');out.append(f.channel).append(':').append(f.flags).append(':').append(f.total).append(':').append(hex(f.body));}return out.toString();}
 private static String rejection(byte[] wire,boolean oracle,boolean logical){try{if(oracle){List<ReferenceWireOracle.Frame> f=ReferenceWireOracle.parse(wire);if(logical)ReferenceWireOracle.reassemble(f);}else{List<AaFrame> f=frames(wire,new int[]{wire.length});if(logical)assemble(f);}return "ACCEPT";}catch(IllegalArgumentException e){return e.getClass().getName()+":"+e.getMessage();}catch(IllegalStateException e){return e.getClass().getName()+":"+e.getMessage();}}
 private static void golden(File directory)throws Exception{
  BufferedReader input=new BufferedReader(new InputStreamReader(new FileInputStream(new File(directory,"cases.tsv")),"UTF-8"));int count=0;
  try{String line;while((line=input.readLine())!=null){String[] f=line.split("\t",-1);if(f.length!=5)throw new AssertionError("Golden TSV shape");byte[] wire=read(new File(directory,f[0]+".bin"));check("golden SHA "+f[0],hex(MessageDigest.getInstance("SHA-256").digest(wire)).equalsIgnoreCase(f[4]));boolean logical=f[1].equals("wire");
   if(f[2].equals("REJECT")){check("golden dual rejection "+f[0],!rejection(wire,true,logical).equals("ACCEPT")&&!rejection(wire,false,logical).equals("ACCEPT"));}
   else if(logical){String ref=referenceMessages(ReferenceWireOracle.reassemble(ReferenceWireOracle.parse(wire)));String actual=productionMessages(assemble(frames(wire,new int[]{wire.length})));check("golden logical oracle "+f[0],ref.equals(f[3])&&actual.equals(f[3]));for(int cut=0;cut<=wire.length;cut++)property("golden every transport split",productionMessages(assemble(frames(wire,new int[]{cut,wire.length-cut}))).equals(ref));int[] ones=new int[wire.length];Arrays.fill(ones,1);property("golden one-byte transport logical",productionMessages(assemble(frames(wire,ones))).equals(ref));}
   else if(f[1].equals("frame")){check("golden frame oracle "+f[0],productionFrames(frames(wire,new int[]{wire.length})).equals(f[3])&&referenceFrames(ReferenceWireOracle.parse(wire)).equals(f[3]));int[] ones=new int[wire.length];Arrays.fill(ones,1);property("golden one-byte transport frame",productionFrames(frames(wire,ones)).equals(f[3]));}
   else if(f[1].equals("video")){VideoConfig v=DiscoveryCodec.video(wire);String decoded=v.nominalWidth+":"+v.nominalHeight+":"+v.marginWidth+":"+v.marginHeight+":"+v.dpi+":"+v.fps+":"+v.placement;check("golden video "+f[0],decoded.equals(f[3])&&Arrays.equals(DiscoveryCodec.video(v),wire));}
   else if(f[1].equals("input")){InputConfig i=DiscoveryCodec.touchpad(wire);check("golden input "+f[0],(i.width+":"+i.height+":"+i.physicalWidthMm+":"+i.physicalHeightMm+":"+i.uiNavigation+":"+i.uiAbsolute).equals(f[3])&&Arrays.equals(DiscoveryCodec.touchpad(i),wire));}
   else if(f[1].equals("open")){ControlMessages.Open o=ControlMessages.Open.parse(wire);check("golden open "+f[0],(o.priority+":"+o.serviceId).equals(f[3])&&Arrays.equals(o.encode(),wire));}
   else if(f[1].equals("proto")){ProtoWire.Message p=ProtoWire.parse(wire);check("golden lossless unknown fields "+f[0],p.scalar(1,true,0)==150&&Arrays.equals(p.encoded(),wire));}
   else throw new AssertionError("Unknown fixture kind");count++;
  }}finally{input.close();}check("golden fixture inventory",count==28);
 }
 private static byte[] validWire(){
  int messages=1+random.nextInt(5);List<List<ReferenceWireOracle.Frame>> queues=new ArrayList<List<ReferenceWireOracle.Frame>>();Set<Integer> channels=new HashSet<Integer>();
  for(int m=0;m<messages;m++){int c;do{c=random.nextInt(256);}while(!channels.add(c));byte[] body=new byte[2+random.nextInt(1023)];random.nextBytes(body);int pieces=1+random.nextInt(8);int[] cuts=new int[pieces+1];cuts[0]=0;cuts[pieces]=body.length;for(int i=1;i<pieces;i++)cuts[i]=random.nextInt(body.length+1);Arrays.sort(cuts);int[] sizes=new int[pieces];for(int i=0;i<pieces;i++)sizes[i]=cuts[i+1]-cuts[i];queues.add(ReferenceWireOracle.fragment(c,random.nextBoolean()?4:0,body,sizes));}
  List<ReferenceWireOracle.Frame> frames=new ArrayList<ReferenceWireOracle.Frame>();while(!queues.isEmpty()){int q=random.nextInt(queues.size());List<ReferenceWireOracle.Frame> queue=queues.get(q);frames.add(queue.remove(0));if(queue.isEmpty())queues.remove(q);}return ReferenceWireOracle.encode(frames);
 }
 private static void differential(){
  long start=System.nanoTime();
  for(int trial=0;trial<5000;trial++){if(System.nanoTime()-start>45000000000L)throw new AssertionError("Differential time limit");byte[] wire=validWire();List<ReferenceWireOracle.Frame> refFrames=ReferenceWireOracle.parse(wire);List<AaFrame> actualFrames=frames(wire,chunks(wire.length));property("independent frame parser",productionFrames(actualFrames).equals(referenceFrames(refFrames)));property("independent logical reassembly",productionMessages(assemble(actualFrames)).equals(referenceMessages(ReferenceWireOracle.reassemble(refFrames))));
   ByteArrayOutputStream productionBytes=new ByteArrayOutputStream();for(AaFrame f:actualFrames){byte[] b=new AaFrameWriter().encode(f);productionBytes.write(b,0,b.length);}property("independent encoding equality",Arrays.equals(productionBytes.toByteArray(),wire));validCases++;
  }
  String[] malformed={"001300020001","000300","00030004000100","020200020001","02010002000000040001020300020001","02010002000000040001020600020002","020100020000000400010202000102","020100020000000200010202000102","02010000ffffffff","0201000000010001"};
  for(int trial=0;trial<2500;trial++){String base=malformed[random.nextInt(malformed.length)];byte[] wire=IndependentFixtures.hex(base);String oracle=rejection(wire,true,true),one=rejection(wire,false,true),two=rejection(wire,false,true);property("malformed dual rejection",!oracle.equals("ACCEPT")&&!one.equals("ACCEPT"));property("malformed deterministic production failure",one.equals(two));malformedCases++;}
  check("independent differential batch completed",validCases==5000&&malformedCases==2500);
 }
 private static void retentionAndBounds(){
  byte[] unknown=IndependentFixtures.hex("089681007a03010203810101020304050607088d0101020304"); // intentionally nonminimal scalar150 in field1
  ProtoWire.Message m=ProtoWire.parse(unknown);check("generic passthrough preserves noncanonical encoding/order",Arrays.equals(unknown,m.encoded()));check("unknown bytes filter excludes known field",Arrays.equals(m.unknownFields(1),Arrays.copyOfRange(unknown,4,unknown.length)));
  byte[] first=m.fields().get(0).encoded();first[0]=0;check("raw field bytes immutable",m.fields().get(0).encoded()[0]==8);byte[] full=m.encoded();full[0]=0;check("message output immutable",m.encoded()[0]==8);
  byte[] discovery=Arrays.copyOf(IndependentFixtures.DISCOVERY,IndependentFixtures.DISCOVERY.length+2);discovery[discovery.length-2]=120;discovery[discovery.length-1]=1;DiscoveryCodec.Decoded decoded=DiscoveryCodec.decode(discovery);check("discovery unknown root passthrough",Arrays.equals(decoded.originalEncoding(),discovery));byte[] original=decoded.originalEncoding();original[0]=0;check("discovery retained bytes immutable",decoded.originalEncoding()[0]!=0);
  byte[] nested=IndependentFixtures.hex("0a1508021a11220d080210011800202028e501780108031201501a014d2201592a0030003a01484201554a01425201565800");
  // A fully independent nested fixture is inspected below; unknown video field15 is retained in raw original.
  DiscoveryCodec.Decoded nestedDecoded=DiscoveryCodec.decode(nested);check("discovery nested unknown retained",Arrays.equals(nestedDecoded.originalEncoding(),nested)&&nestedDecoded.video.get(0).activeHeight()==688);
  AaMessageAssembler a=new AaMessageAssembler(65536,8,524288);a.accept(new AaFrame(1,1,4,new byte[]{0}));a.accept(new AaFrame(2,1,4,new byte[]{0}));boolean failed=false;try{a.accept(new AaFrame(1,2,-1,new byte[]{1}));}catch(IllegalArgumentException expected){failed=true;}check("one malformed channel invalidates session explicitly",failed&&a.isFailed()&&a.activeChannels()==0&&a.reservedBytes()==0);a.reset();check("unrelated channel not silently resumed after error",a.activeChannels()==0&&!a.isFailed());
  for(int repetition=0;repetition<100;repetition++){AaMessageAssembler pending=new AaMessageAssembler(65536,8,524288);pending.accept(new AaFrame(1,1,65536,new byte[0]));for(int i=1;i<256;i++)pending.accept(new AaFrame(1,0,-1,new byte[0]));boolean rejected=false;try{pending.accept(new AaFrame(1,0,-1,new byte[0]));}catch(IllegalArgumentException expected){rejected=true;}property("empty fragments cannot persist beyond cap",rejected&&pending.reservedBytes()==0&&pending.activeChannels()==0&&pending.isFailed());}
  byte[] payload=new byte[65532];byte[] nearLimit=new ProtoWire.Writer().bytes(15,payload).finish();ProtoWire.Message bounded=ProtoWire.parse(nearLimit);check("lossless retention at protobuf byte ceiling",nearLimit.length==65536&&bounded.encoded().length==65536);
 }
 public static void main(String[] args)throws Exception{if(args.length!=1)throw new IllegalArgumentException("Golden fixture directory required");golden(new File(args[0]));retentionAndBounds();differential();System.out.println("RESULT PASS deterministic="+deterministic+" propertyChecks="+propertyChecks+" validCases="+validCases+" malformedCases="+malformedCases+" seed="+SEED+"; INDEPENDENT HOST ORACLE ONLY; no device IO");}
}
